## Code Example
```javascript
function maxSumKSubarrays(A, k, c) {
  const n = A.length;
  const NEG = -1e15;
  const end = Array.from({length: n+1}, () => Array(k+1).fill(NEG));
  const best = Array.from({length: n+1}, () => Array(k+1).fill(NEG));
  best[0][0] = 0;
  for (let i=1; i<=n; i++) {
    for (let t=0; t<=k; t++) {
      end[i][t] = Math.max(end[i-1][t] + A[i-1], t>0 ? best[i-1][t-1] + A[i-1] : NEG);
      best[i][t] = Math.max(best[i-1][t], end[i][t] - c);
    }
  }
  return {value: best[n][k], subs: null};
}
```

